# The sheet's audit lines as the audit file holds them, newest first; ?name= keeps those about that person.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.audit.RespondWithAuditLines
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.audit;

import java.util.List;

/** A sheet's audit lines, exactly as the audit file holds them, newest first. */
public record AuditLinesResponse(List<String> lines) {
}
package net.officefloor.hq.app.audit;

import jakarta.servlet.http.HttpServletRequest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/**
 * The audit viewer: the sheet's lines read from the audit file (it is not a second record), newest
 * first. With a name in {@code ?name=} only the lines carrying {@code name=} or {@code person=} that
 * name, compared as names are compared (case and surrounding spaces ignored). When that name is a
 * person on the sheet transferred from another sheet, the lines about them from the sheet they came
 * from follow, newest first, as that sheet's file holds them.
 */
public class RespondWithAuditLines {
    public void respond(@Val Sheet sheet, Audit audit, PersonRepository people, HttpServletRequest request,
            ObjectResponse<AuditLinesResponse> response) {
        String name = request.getParameter("name");
        name = name == null ? "" : name;
        List<String> lines = new ArrayList<>(audit.linesFor(sheet.id(), name));
        Collections.reverse(lines);
